from xat_cases.legacy.bgm.VehicleCloud.DigitalKey.case_helper.test_digital_key_baseclass_abc import *
from xat_ecu.api.abc_interface import *

@allure.feature("互联服务")
@allure.story("数字钥匙和账号/RKE/蓝牙车门控制")
class TestDigitalKeyDoorControl(TestDigitalKeyBase):
    def before_each_func(self, ecu):
        """每个测试用例前置步骤"""
        super().before_each_func(ecu)
        self.io.set_five_door_sts(Door.close)
        self.soa.hmi_set_door_close_lock(LockCmd.Lock, LockSource.RKE)
        self.bus_comm.set_door_warning_ThermalProtection_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        self.bus_comm.set_door_warning_FaultPlayProtectionActive_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        self.bus_comm.set_door_warning_RollAngleAbnormal_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        self.bus_comm.set_door_warning_RoadInclinationAbnormal_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        self.bus_comm.set_door_warning_HallSensorsError_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        sleep(3)

    def after_class(self, ecu):
        try:
            self.mix.set_common_precontion(
                usage_mode=UsageMode.INACTIVE, car_mode=CarMode.NORMAL
            )
            self.bus_comm.set_engine_and_check_energy_level(engine= EngSt1WdStsEngSt1WdSts.EngSt1_Ini)
        except Exception as e:
            logger.info(f"----------> after_class Error{str(e)}")
            pass
    
    def after_each_func(self, ecu):
        """每个测试用例后置步骤"""
        super().after_each_func(ecu)
        self.soa.hmi_set_door_close_lock(LockCmd.Lock, LockSource.RKE)
        self.io.set_five_door_sts(Door.close)
        self.bus_comm.dk.empty_dk_data_queue()
        self.bus_comm.set_door_warning_ThermalProtection_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        self.bus_comm.set_door_warning_FaultPlayProtectionActive_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        self.bus_comm.set_door_warning_RollAngleAbnormal_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        self.bus_comm.set_door_warning_RoadInclinationAbnormal_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        self.bus_comm.set_door_warning_HallSensorsError_sts(Drvr=False,Pass=False,LeRe=False,RiRe=False)
        sleep(3)

    @allure.title("RKE车门控制请求_ABANDONED")
    @pytest.mark.smoke
    def test_caseid_1996876(self):
        self.bus_comm.dk.send_rke_driver_door(op = 1, position = 5)
        self.bus_comm.dk.ck_rke_resp(33, 0, "PreConditionOK", exec_type=2,timeout=20)
        sleep(10)

