    def test_caseid_1996283(self):
        self.bus_comm.dk.empty_dk_data_queue()
        self.mix.set_usage_mode(usage_mode=UsageMode.INACTIVE)
        sleep(.5)
        self.bus_comm.dk.send_rke_four_door(op=1, driverPosition=100, passengerPosition=100, rearLeftPosition=100, rearRightPosition=100)
        self.bus_comm.check_door_open_pos_and_trigsrc(doorpos=DoorPos.RearRight, position=100, door_trigsrc=DoorTrigerSource.NoTrigSrc)
        self.bus_comm.dk.ck_rke_resp(cmd_code=37, code=0, msg="PreConditionOK", exec_type=2,timeout=20) 
        self.bus_comm.set_four_door_opener_sts(door_opener=DoorOpenerSts.FullOpend)  
        self.bus_comm.dk.ck_rke_resp(cmd_code=37, code=0, msg="Success", exec_type=3,timeout=20)
        self.bus_comm.dk.send_rke_driver_door(op=2, position=0)
        self.bus_comm.check_door_opener_req_and_trigsrc(drv_opener=DoorPos.Dirver, door_req= DoorOpenerReq.Close, door_trigsrc=DoorTrigerSource.HMI, timeout=5)        
        self.bus_comm.dk.ck_rke_resp(cmd_code=33, code=0, msg="PreConditionOK", exec_type=2,timeout=20) 
        self.bus_comm.dk.send_rke_rear_right_door(op=2, position=0)
        self.bus_comm.check_door_opener_req_and_trigsrc(rire_opener=DoorPos.RearRight, door_req= DoorOpenerReq.Close, door_trigsrc=DoorTrigerSource.HMI)        
        self.bus_comm.dk.ck_rke_resp(cmd_code=36, code=0, msg="PreConditionOK", exec_type=2,timeout=20) 
        self.bus_comm.dk.send_rke_rear_left_door(op=2, position=0)
