    @allure.title("RKE车门控制请求_开左前门_闭锁联动关门")
    @pytest.mark.sanity
    def test_caseid_1996506(self):
        self.bus_comm.dk.empty_dk_data_queue()
        self.mix.set_usage_mode(usage_mode=UsageMode.INACTIVE)
        sleep(.5)
        self.bus_comm.dk.send_rke_driver_door(op=1,position=100)
        self.bus_comm.check_door_open_pos_and_trigsrc(doorpos=DoorPos.Dirver,position=100,door_trigsrc=DoorTrigerSource.NoTrigSrc)
        self.bus_comm.dk.ck_rke_resp(cmd_code=33, code=0, msg="PreConditionOK", exec_type=2,timeout=20) 
        self.bus_comm.dk.send_rke_close_door_and_lock()
        self.bus_comm.dk.ck_rke_resp(1, 0, "PreConditionOK", exec_type=2,timeout=20)
        self.bus_comm.dk.ck_rke_resp(1, 0, "Success", exec_type=3,timeout=20)
