        self.bus_comm.dk.send_rke_four_door(op = 1,driverPosition=100,passengerPosition=100,rearLeftPosition=100,rearRightPosition=100)
        self.bus_comm.dk.ck_rke_resp(37, 0, "PreConditionOK", exec_type=2,timeout=20)
        self.soa.ck_key_service_unlock_event(keyid=key_id0,key_type=DigitalKeyType.BLE_Key,trigger=DigitalKeyIdTrigger.Unlock)
        # self.soa.check_vehicle_inside_person_sts(userInVehicleStatus=True,userInVehicleStatusWithCam=True)
        self.bus_comm.check_door_open_pos_and_trigsrc(doorpos=DoorPos.RearLeft,position=100,door_trigsrc=DoorTrigerSource.NoTrigSrc,timeout=5)
        self.bus_comm.set_door_opener_sts(drv_opener=DoorOpenerSts.FullOpend,pass_opener=DoorOpenerSts.FullOpend,lere_opener=DoorOpenerSts.FullOpend,rire_opener=DoorOpenerSts.FullOpend)
        self.bus_comm.dk.ck_rke_resp(37, 0, "Success", exec_type=3, timeout=20)